outputs.output:
{
  "title": "Should we roll out the new checkout button?",
  "setting": "Morning at Kite Commerce",
  "mission": "Evaluate early A/B test results to determine if a 2% lift is real, and **recommend whether to launch now or keep testing**.",
  "deadline": "Product sync today at 2:00 p.m.",
  "panels": [
    {
      "title": "Checkout A/B test (Day 1)",
      "metrics": [
        {
          "label": "Button A (control)",
          "value": "5.0%",
          "note": "25 buys / 500 visits"
        },
        {
          "label": "Button B (new)",
          "value": "7.0%",
          "note": "35 buys / 500 visits"
        },
        {
          "label": "Observed gap",
          "value": "+2.0%",
          "note": "40% relative lift"
        }
      ],
      "note": "Experiment ran for 24 hours across 1,000 total shoppers."
    }
  ],
  "team": [
    {
      "id": "growth",
      "role": "Growth marketer",
      "expertise": "Conversion campaigns, site traffic, and campaign deadlines",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Feature releases, roadmap speed, and business targets",
      "ai": false
    },
    {
      "id": "ai",
      "role": "Data analytics assistant",
      "expertise": "Sample size sizing, significance calculations, and error checks",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a false win",
      "start": 50,
      "goodWhen": "low"
    },
    {
      "id": "alignment",
      "label": "Team confidence",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "tell-chance",
      "name": "Tell a real difference from chance",
      "practice": "Look at two conversion rates and state whether random luck could explain a 10-person lead."
    },
    {
      "id": "sample-size",
      "name": "Choose a sample size",
      "practice": "Estimate how many visitors an A/B test needs to reliably catch a 2 percentage point bump."
    },
    {
      "id": "explain-result",
      "name": "Explain a test result",
      "practice": "Summarize why a test needs more data in one plain sentence without using technical jargon."
    }
  ],
  "startNodeId": "first-look",
  "nodes": [
    {
      "id": "first-look",
      "messages": [
        {
          "from": "growth",
          "text": "Button B is up by two full percentage points after just one day! That is a huge 40% jump."
        },
        {
          "from": "product",
          "text": "I want to ship Button B to all shoppers before our afternoon roadmap review. Can we call it a win?"
        }
      ],
      "prompt": "How do you respond to {{product}} and {{growth}}?",
      "choices": [
        {
          "id": "launch-now",
          "text": "Declare Button B the winner and ship it immediately to lock in the lift.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Awesome. Pushing Button B to 100% of our checkout traffic now."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 40
            },
            {
              "meter": "alignment",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-chance",
              "kind": "improve",
              "text": "You rolled out a change with only 10 extra purchases, which is very likely random variance.",
              "example": "\"Ten extra orders over 500 visits could easily happen by pure chance, so let's check statistical significance first.\""
            }
          ],
          "next": "hasty-ship"
        },
        {
          "id": "ask-ai-significance",
          "text": "Ask {{ai}} whether a 10-purchase lead across 500 shoppers per group could just be chance.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "With 25 vs 35 conversions out of 500 each, there is about an 18% chance of seeing this gap purely by luck. The difference is not statistically significant."
            },
            {
              "from": "growth",
              "text": "Wait, an 18% chance of pure luck? That sounds way too risky to bet the store on."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "alignment",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-chance",
              "kind": "good",
              "text": "You checked whether the lead exceeded normal random variation before making a major release.",
              "example": null
            }
          ],
          "next": "decide-sample"
        },
        {
          "id": "reject-immediately",
          "text": "Tell them Button B failed to prove itself and switch back to the original design.",
          "quality": "fair",
          "replies": [
            {
              "from": "growth",
              "text": "Failed? But it was ahead! Why kill an idea that might actually be better?"
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 10
            },
            {
              "meter": "alignment",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-chance",
              "kind": "improve",
              "text": "Lack of evidence today does not mean Button B is worse; it just means the sample is too small.",
              "example": "\"A non-significant lead doesn't mean Button B doesn't work; we just need enough data to be sure.\""
            }
          ],
          "next": "decide-sample"
        }
      ]
    },
    {
      "id": "decide-sample",
      "messages": [
        {
          "from": "product",
          "text": "If 1,000 visitors isn't enough, how much longer do we have to run this test?"
        },
        {
          "from": "growth",
          "text": "Traffic is steady at 1,000 visitors a day. Can we finish this test by tomorrow morning?"
        }
      ],
      "prompt": "What do you suggest for the test duration and sample size?",
      "choices": [
        {
          "id": "ask-sample-sizing",
          "text": "Ask {{ai}} to calculate the exact sample size needed to confirm a 2% lift with standard 95% confidence.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "To detect a move from 5% to 7% reliably, we need around 2,500 visitors per variation—5,000 total. That takes about 4 more days."
            },
            {
              "from": "product",
              "text": "Four days is doable if it keeps us from making an expensive mistake on checkout."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "alignment",
              "change": 20
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "Checkout A/B test (Day 5)",
              "metrics": [
                {
                  "label": "Button A (control)",
                  "value": "5.1%",
                  "note": "128 buys / 2,500 visits"
                },
                {
                  "label": "Button B (new)",
                  "value": "7.2%",
                  "note": "180 buys / 2,500 visits"
                },
                {
                  "label": "Observed gap",
                  "value": "+2.1%",
                  "note": "Statistically significant"
                }
              ],
              "note": "Test completed with 5,000 total visitors and 95% confidence."
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "good",
              "text": "You sized the experiment beforehand so the test would have enough power to spot the true effect.",
              "example": null
            }
          ],
          "next": "final-explanation"
        },
        {
          "id": "guess-one-day",
          "text": "Run it for just one more day to reach 2,000 visitors, then make the final call.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "One day sounds fast. Let's see what the numbers look like tomorrow."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "alignment",
              "change": 5
            }
          ],
          "timeJump": {
            "label": "One day later",
            "panel": {
              "title": "Checkout A/B test (Day 2)",
              "metrics": [
                {
                  "label": "Button A (control)",
                  "value": "5.4%",
                  "note": "54 buys / 1,000 visits"
                },
                {
                  "label": "Button B (new)",
                  "value": "6.5%",
                  "note": "65 buys / 1,000 visits"
                },
                {
                  "label": "Observed gap",
                  "value": "+1.1%",
                  "note": "Still inconclusive"
                }
              ],
              "note": "Sample is still too small to rule out ordinary fluctuation."
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "improve",
              "text": "Picking arbitrary test lengths leaves you stuck with inconclusive results when data is thin.",
              "example": "\"Let's calculate the required sample size so we run the test exactly long enough to be confident.\""
            }
          ],
          "next": "final-explanation"
        }
      ]
    },
    {
      "id": "final-explanation",
      "messages": [
        {
          "from": "product",
          "text": "The meeting with leadership starts in 15 minutes. How should we explain this to them in simple terms?"
        },
        {
          "from": "growth",
          "text": "They don't know statistics. Keep it grounded so they understand our recommendation."
        }
      ],
      "prompt": "How do you explain the findings to leadership?",
      "choices": [
        {
          "id": "explain-plainly",
          "text": "Explain that coin flips can show streaks in small samples, but larger data proved Button B genuinely wins.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That coin flip comparison makes immediate sense. Leadership will easily buy into that reasoning."
            },
            {
              "from": "growth",
              "text": "Clear, honest, and backed by solid numbers. Let's present it exactly like that."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "alignment",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "good",
              "text": "You translated sample variability into an intuitive analogy that non-analysts can follow.",
              "example": null
            }
          ],
          "next": "end-success"
        },
        {
          "id": "explain-jargon",
          "text": "Tell them our p-value was 0.18 initially, so we held back until rejecting the null hypothesis at alpha 0.05.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Leadership is going to tune out if we start throwing Greek letters and textbook terms at them."
            },
            {
              "from": "growth",
              "text": "I'll try to rephrase it in the meeting so they don't get lost."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 5
            },
            {
              "meter": "alignment",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "improve",
              "text": "Relying on textbook definitions like null hypothesis confuses stakeholders who want practical context.",
              "example": "\"Early on, the lead was small enough that lucky timing could explain it; after collecting full data, the lead held up.\""
            }
          ],
          "next": "end-mixed"
        }
      ]
    },
    {
      "id": "hasty-ship",
      "messages": [
        {
          "from": "growth",
          "text": "We shipped Button B, but over the next three days the overall conversion rate actually slipped back to 5.1%."
        },
        {
          "from": "product",
          "text": "Wait, what happened to our 7% conversion rate? Did the lift just disappear?"
        }
      ],
      "prompt": "What do you tell {{product}} now?",
      "choices": [
        {
          "id": "own-mistake",
          "text": "Explain that the first day was random fluctuation, and propose running formal tests with proper sample sizes going forward.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Painful lesson, but good to know. Let's set up mandatory sample size rules for our next sprint."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "alignment",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "good",
              "text": "You clearly linked the disappointing outcome to random sample variance rather than placing blame.",
              "example": null
            }
          ],
          "next": "end-cautionary"
        },
        {
          "id": "blame-traffic",
          "text": "Argue that customer traffic quality must have dropped after the release date.",
          "quality": "weak",
          "replies": [
            {
              "from": "growth",
              "text": "Our ad channels didn't change at all. That explanation doesn't match our analytics."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 20
            },
            {
              "meter": "alignment",
              "change": -25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-chance",
              "kind": "improve",
              "text": "Inventing external excuses obscures the real issue: shipping before ruling out random noise.",
              "example": "\"The initial spike was just random noise in a small sample, not a change in our audience.\""
            }
          ],
          "next": "end-cautionary"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "end-success",
      "outcome": "With a verified sample of 5,000 shoppers, Button B delivered an authentic 2.1% conversion lift, boosting revenue by thousands of dollars each week."
    },
    {
      "id": "end-mixed",
      "outcome": "Button B was deployed successfully, but confusing presentations created friction with leadership and slowed down approval for future experiments."
    },
    {
      "id": "end-cautionary",
      "outcome": "Button B was launched on noisy data, and conversion rates returned to baseline. The team adopted standard sample size checks to avoid false alarms."
    }
  ],
  "summary": [
    "A small lead in an experiment can easily be random chance rather than a genuine improvement.",
    "Calculate sample size requirements before drawing conclusions to avoid premature decisions.",
    "Explain statistical findings with tangible everyday analogies rather than technical formulas."
  ]
}

{
  "title": "E se a luz gotejasse como água?",
  "setting": "Uma tarde no Laboratório Imaginário",
  "mission": "Explorar o que aconteceria se pudéssemos desacelerar a luz e ver a energia **saindo em pacotes mínimos** em vez de um fluxo contínuo.",
  "deadline": null,
  "panels": [
    {
      "title": "Experimento com a lanterna",
      "metrics": [
        {
          "label": "Intensidade da luz",
          "value": "Mínima",
          "note": "Quase no limite de apagar"
        },
        {
          "label": "Sensor de energia",
          "value": "Pulsos",
          "note": "Cliques individuais"
        }
      ],
      "note": "A luz parece um jato suave a olho nu, mas o sensor revela pequenos disparos discretos."
    }
  ],
  "team": [
    {
      "id": "physicist",
      "role": "Divulgadora científica",
      "expertise": "Cria analogias simples para explicar o mundo microscópico",
      "ai": false
    },
    {
      "id": "friend",
      "role": "Curioso da turma",
      "expertise": "Faz perguntas do dia a dia sobre fenômenos estranhos",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "understanding",
      "label": "Clareza da ideia",
      "start": 20,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "energy-packets",
      "name": "Energia em pacotes",
      "practice": "Descreva para um amigo como a luz é como chuva em vez de um rio contínuo."
    },
    {
      "id": "wave-particle",
      "name": "Dualidade onda-partícula",
      "practice": "Dê um exemplo cotidiano de algo que viaja como onda mas bate como pedrinha."
    }
  ],
  "startNodeId": "dimmer-choice",
  "nodes": [
    {
      "id": "dimmer-choice",
      "messages": [
        {
          "from": "physicist",
          "text": "Imagine que este botão reduz a luz do abajur até o limite extremo do universo. O que você acha que vai acontecer se reduzirmos ao máximo?"
        },
        {
          "from": "friend",
          "text": "Acho que a luz vai virar um fiozinho infinitamente fininho e suave, como água escorrendo devagar de uma torneira."
        }
      ],
      "prompt": "Como você testa o que acontece no limite mínimo da luz?",
      "choices": [
        {
          "id": "click-counter",
          "text": "Reduzo o brilho ao menor nível possível e escuto o detector de energia.",
          "quality": "strong",
          "replies": [
            {
              "from": "physicist",
              "text": "Olha o som: 'Tique... tique... tique'. A luz não enfraquece infinitamente; ela chega em pacotinhos indivisíveis chamados fótons!"
            },
            {
              "from": "friend",
              "text": "Nossa, parece granizo batendo na janela! Então não tem meio pacote?"
            }
          ],
          "effects": [
            {
              "meter": "understanding",
              "change": 40
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "energy-packets",
              "kind": "good",
              "text": "Você investigou o comportamento granular da energia em vez de assumir um fluxo contínuo.",
              "example": null
            }
          ],
          "next": "slit-test"
        },
        {
          "id": "color-filter",
          "text": "Troco a lâmpada por uma luz vermelha fraca para ver se ela escorre sem fazer barulho.",
          "quality": "fair",
          "replies": [
            {
              "from": "physicist",
              "text": "A cor muda a energia de cada pacote, mas ainda ouvimos cliques espaçados. A energia nunca escorre de forma lisa."
            }
          ],
          "effects": [
            {
              "meter": "understanding",
              "change": 20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "energy-packets",
              "kind": "improve",
              "text": "Trocar a cor altera o tamanho de cada pacote, mas o ponto central é que a luz sempre chega em unidades inteiras.",
              "example": "\"Vamos diminuir a intensidade até ver se o fluxo se divide em pedacinhos.\""
            }
          ],
          "next": "slit-test"
        },
        {
          "id": "smooth-flow",
          "text": "Concordo que ela vai virar um fio contínuo e tento focar a luz com uma lupa comum.",
          "quality": "weak",
          "replies": [
            {
              "from": "friend",
              "text": "Parece que continua suave a olho nu, mas o aparelho começou a apitar em pulsos isolados."
            },
            {
              "from": "physicist",
              "text": "Nossos olhos integram tudo e dão ilusão de continuidade, mas a física quântica mostra que a energia chega em blocos fechados."
            }
          ],
          "effects": [
            {
              "meter": "understanding",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "energy-packets",
              "kind": "improve",
              "text": "Você confiou na intuição visual em vez de observar a medição discreta.",
              "example": "\"Vamos usar o detector para conferir se a energia chega de uma vez ou em pequenos blocos.\""
            }
          ],
          "next": "slit-test"
        }
      ]
    },
    {
      "id": "slit-test",
      "messages": [
        {
          "from": "friend",
          "text": "Se a luz é feita dessas 'pedrinhas' de energia, então quando disparamos uma a uma contra duas frestas na parede, elas deveriam formar duas pilhas retas, certo?"
        },
        {
          "from": "physicist",
          "text": "Boa aposta! Vamos deixar a máquina disparar um pacote por vez durante a noite contra a tela."
        }
      ],
      "prompt": "O que você decide olhar no dia seguinte para desvendar o mistério?",
      "choices": [
        {
          "id": "check-pattern",
          "text": "Examino a marca acumulada na tela para ver se formou listras de ondas ou duas linhas de partículas.",
          "quality": "strong",
          "replies": [
            {
              "from": "physicist",
              "text": "Sensacional! Cada fóton bateu como um ponto solitário, mas juntos eles formaram listras claras e escuras típicas de ondas!"
            },
            {
              "from": "friend",
              "text": "Que doideira: ele viaja como onda pelo espaço, mas acerta o alvo como uma partícula pontual!"
            }
          ],
          "effects": [
            {
              "meter": "understanding",
              "change": 40
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "wave-particle",
              "kind": "good",
              "text": "Você verificou a dualidade onda-partícula observando como eventos individuais criam um padrão ondulatório coletivo.",
              "example": null
            }
          ],
          "next": "end-quantum-nature"
        },
        {
          "id": "block-one-slit",
          "text": "Tampo uma das frestas imediatamente para forçar cada pacote a se comportar como bolinha de gude.",
          "quality": "fair",
          "replies": [
            {
              "from": "physicist",
              "text": "Ao tampar uma fresta, as listras somem e sobra apenas uma faixa. Perdemos a chance de ver a onda interferindo consigo mesma."
            }
          ],
          "effects": [
            {
              "meter": "understanding",
              "change": 20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "wave-particle",
              "kind": "improve",
              "text": "Tampar a fresta destrói a interferência ondulatória antes de você conseguir observar o fenômeno completo.",
              "example": "\"Vamos deixar as duas frestas abertas primeiro para comparar o padrão com o de ondas na água.\""
            }
          ],
          "next": "end-partial-glimpse"
        },
        {
          "id": "assume-balls",
          "text": "Concluo que são apenas bolinhas comuns e nem preciso olhar a tela.",
          "quality": "weak",
          "replies": [
            {
              "from": "friend",
              "text": "Espere, olhei a tela por curiosidade e tem várias faixas paralelas! Bolinhas normais nunca fariam isso!"
            },
            {
              "from": "physicist",
              "text": "A intuição comum falha aqui: a luz se comporta ora como onda que se espalha, ora como partícula concentrada."
            }
          ],
          "effects": [
            {
              "meter": "understanding",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "wave-particle",
              "kind": "improve",
              "text": "Assumir que o pacote se comporta como uma esfera rígida ignora o aspecto ondulatório da luz.",
              "example": "\"Vamos conferir a tela: mesmo sendo pacotes, eles criam desenhos de interferência como ondas na praia.\""
            }
          ],
          "next": "end-partial-glimpse"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "end-quantum-nature",
      "outcome": "Você descobriu que no fundo do universo a luz não é um rio contínuo nem bolinhas duras: ela viaja como onda e se entrega em pacotes indivisíveis chamados quanta."
    },
    {
      "id": "end-partial-glimpse",
      "outcome": "Você percebeu que a luz não é contínua, mas quase perdeu sua faceta ondulatória por tentar encaixá-la nas regras do mundo visível."
    }
  ],
  "summary": [
    "A energia da luz não flui de maneira infinitamente contínua; ela sempre é emitida e absorvida em pacotes mínimos chamados quanta.",
    "A luz exibe dualidade onda-partícula: viaja pelo espaço exibindo interferência de onda, mas colide e transfere energia como partícula."
